    18	func installMissingPlugin(ctx context.Context, rootCmd *cobra.Command, name string) (string, error) {
    19		// The plugin may already be in the managed directory and merely
    20		// unreachable through PATH — a managed bin dir that could not be
    21		// prepended at startup. Offering to install over it is a dead end:
    22		// installRepoAtTag refuses an existing install without --force, which the
    23		// on-demand path deliberately does not pass, so the user answers Yes,
    24		// waits for three network round-trips and gets "already installed; use
    25		// --force to replace". Execute the managed entry instead, which is what
    26		// this function's own return contract promises below.
    27		//
    28		// A listing error falls through to the install rather than failing here:
    29		// the install path reads the same directory and reports the problem in
    30		// terms of what it was trying to do.
    31		if installed, err := FindInstalledPlugin(name); err == nil && installed != nil {
    32			// The entry is not necessarily runnable. ListInstalledPlugins reports
    33			// what it finds with Lstat, so a local-dev symlink whose target moved
    34			// is listed like any other install — exec'ing it fails with a
    35			// fork/exec ENOENT that names a path the user never chose and offers
    36			// no way forward. Say what is wrong and how to fix it instead.
    37			//
    38			// Reinstalling automatically would be the other option, and it is
    39			// deliberately not taken: replacing a developer's deliberate symlink
    40			// with a released binary is their call to make, not ours.
    41			if reinstallFixes, cerr := checkManagedPluginRunnable(installed.Path); cerr != nil {
    42				broken := fmt.Errorf("the entire-%s plugin is installed at %s but cannot be run: %w", name, installed.Path, cerr)
    43				if !reinstallFixes {
    44					return "", broken
    45				}
    46				return "", fmt.Errorf("%w; reinstall it with 'entire plugin install %s --force'", broken, name)
    47			}
    48			return installed.Path, nil
    49		}
    50		if !interactive.CanPromptInteractively() {
    51			return "", fmt.Errorf("the entire-%s plugin is not installed; run 'entire plugin install %s' and retry", name, name)
    52		}
    53		if err := ctx.Err(); err != nil {
    54			return "", fmt.Errorf("install plugin: %w", err)
    55		}
    56		confirmed, err := runPluginConfirm(ctx, rootCmd.ErrOrStderr(), fmt.Sprintf("Install the entire-%s plugin?", name), true)
    57		if err != nil {
    58			if ctx.Err() != nil {
    59				return "", err
    60			}
    61			return "", handleFormCancellation(rootCmd.ErrOrStderr(), "Install", err)
    62		}
    63		if !confirmed {
    64			fmt.Fprintln(rootCmd.ErrOrStderr(), "Install cancelled.")
    65			return "", nil
    66		}
    67		if err := ctx.Err(); err != nil {
    68			return "", fmt.Errorf("install plugin: %w", err)
    69		}
    70	
    71		// Keep install progress off stdout: the original command may emit JSON or
    72		// be piped to another tool. Do not parse any of the plugin's arguments.
    73		cmd := newPluginInstallCmd()
    74		cmd.SetOut(rootCmd.ErrOrStderr())
    75		cmd.SetErr(rootCmd.ErrOrStderr())
    76		if err := onDemandPluginInstall(ctx, cmd, installSource{Kind: installFromIndex, Ref: name}, remoteInstallFlags{}); err != nil {
    77			return "", err
    78		}
    79		if err := ctx.Err(); err != nil {
    80			return "", fmt.Errorf("install plugin: %w", err)
    81		}
    82		installed, err := FindInstalledPlugin(name)
    83		if err != nil {
    84			return "", err
    85		}
    86		if installed == nil {
    87			return "", fmt.Errorf("the entire-%s plugin was not installed; run 'entire plugin install %s' and retry", name, name)
    88		}
    89		// Execute the managed entry directly, even if the managed directory could
    90		// not be prepended to PATH at startup.
    91		return installed.Path, nil
    92	}
