    94	// checkManagedPluginRunnable reports why a managed plugin entry cannot be
    95	// executed, or a nil error when it can. reinstallFixes is true only for a
    96	// condition a reinstall actually repairs, so the caller does not attach that
    97	// remedy to an error it would not resolve — a permission failure on the
    98	// managed directory is not fixed by installing into it, and a remedy hung off
    99	// an unmatched error is how advice comes to name the wrong cause (the mistake
   100	// writeEntireDirRemedy documents for `.entire`). It is meaningless when the
   101	// error is nil.
   102	//
   103	// os.Stat rather than Lstat, deliberately: the question is whether the thing
   104	// at the end of the entry exists, and a dangling symlink is the case that
   105	// brought this function into being. The executable bit is left to the exec —
   106	// findInaccessiblePlugin draws the same line for PATH entries, and the mode
   107	// does not mean the same thing on Windows.
   108	func checkManagedPluginRunnable(path string) (reinstallFixes bool, err error) {
   109		info, statErr := os.Stat(path)
   110		if statErr != nil {
   111			if errors.Is(statErr, os.ErrNotExist) {
   112				// Worded rather than passed through because the errno itself ("no
   113				// such file or directory") describes the entry, which plainly
   114				// exists; what is missing is whatever it points at.
   115				return true, errors.New("it points at a file that no longer exists")
   116			}
   117			return false, statErr //nolint:wrapcheck // the caller adds the plugin name and path
   118		}
   119		if info.IsDir() {
   120			return true, errors.New("it is a directory")
   121		}
   122		return false, nil
   123	}
