    16	
    17	// pluginPromptTerminal is the controlling terminal a confirmation prompt uses.
    18	//
    19	// in is the terminal rather than os.Stdin, so a confirmation never consumes
    20	// bytes the plugin was piped. out is the terminal's own output handle, used
    21	// only when the writer the caller supplied is not itself a terminal — see
    22	// runPluginConfirm. It is nil when there is nothing to fall back to, which is
    23	// the case in tests that replace the opener.
    24	type pluginPromptTerminal struct {
    25		in  io.ReadCloser
    26		out io.Writer
    27		// closeOut releases out when it is a handle of its own. Unix hands back
    28		// one file for both directions, so closing in covers it there; Windows
    29		// opens CONIN$ and CONOUT$ separately, and writing to CONIN$ renders
    30		// nothing — which is why the pair cannot be collapsed to one handle.
    31		closeOut func()
    32	}
    33	
    34	// Tests replace the opener rather than redirecting the command's data stream.
    35	var openPluginPromptTerminal = func() (pluginPromptTerminal, error) {
    36		in, out, err := tea.OpenTTY()
    37		if err != nil {
    38			return pluginPromptTerminal{}, fmt.Errorf("open confirmation terminal: %w", err)
    39		}
    40		t := pluginPromptTerminal{in: in, out: out}
    41		if out != in {
    42			t.closeOut = func() { _ = out.Close() }
    43		}
    44		return t, nil
    45	}
    46	
    47	func runPluginConfirm(ctx context.Context, out io.Writer, prompt string, defaultYes bool) (bool, error) {
    48		if err := ctx.Err(); err != nil {
    49			return false, fmt.Errorf("confirmation cancelled: %w", err)
    50		}
    51		term, err := openPluginPromptTerminal()
    52		if err != nil {
    53			return false, err
    54		}
    55		input := term.in
    56		closeInput := sync.OnceFunc(func() { _ = input.Close() })
    57		defer closeInput()
    58		if term.closeOut != nil {
    59			defer term.closeOut()
    60		}
    61		// The answer is read from the terminal, so the question has to be visible
    62		// there. A supplied writer that is not a terminal — `entire graph 2>log`,
    63		// or any wrapper capturing stderr — left the prompt invisible while the
    64		// terminal sat in raw mode waiting for a keypress, and with Yes as the
    65		// default an idle Enter authorized a download-and-exec nobody was shown.
    66		// Render on the terminal the answer comes from instead; the escape
    67		// sequences had no business in the redirect either way.
    68		render := out
    69		if term.out != nil && !interactive.IsTerminalWriter(out) {
    70			render = term.out
    71		}
    72		answer := defaultYes
    73		form := NewAccessibleForm(huh.NewGroup(huh.NewConfirm().Title(prompt).Value(&answer))).WithOutput(render).WithInput(input)
    74		if IsAccessibleMode() {
    75			// Huh's accessible scanner ignores context and treats EOF as the default.
    76			// Make the read cancellable and retain EOF so it cannot authorize an install.
    77			reader, readErr := cancelreader.NewReader(input)
    78			if readErr != nil {
    79				return false, fmt.Errorf("confirmation input: %w", readErr)
    80			}
    81			defer reader.Close()
    82			cancelled := make(chan struct{})
    83			stop := context.AfterFunc(ctx, func() {
    84				if !reader.Cancel() {
    85					// Some platforms cannot cancel reads on a separately opened
    86					// terminal. This descriptor belongs to the prompt, so closing
    87					// it is safe and also releases a blocked read.
    88					closeInput()
    89				}
    90				close(cancelled)
    91			})
    92			defer func() {
    93				if !stop() {
    94					<-cancelled
    95				}
    96			}()
    97			checked := &pluginConfirmReader{Reader: reader}
    98			err = form.WithInput(checked).RunWithContext(ctx)
    99			if ctx.Err() != nil {
   100				return false, fmt.Errorf("confirmation cancelled: %w", ctx.Err())
   101			}
   102			if checked.err != nil {
   103				if errors.Is(checked.err, io.EOF) {
   104					return false, nil
   105				}
   106				return false, fmt.Errorf("confirmation input: %w", checked.err)
   107			}
   108		} else {
   109			err = form.RunWithContext(ctx)
   110		}
   111		if ctx.Err() != nil {
   112			return false, fmt.Errorf("confirmation cancelled: %w", ctx.Err())
   113		}
   114		if err != nil {
   115			return false, fmt.Errorf("confirmation form: %w", err)
   116		}
   117		return answer, nil
   118	}
   119	
   120	type pluginConfirmReader struct {
   121		io.Reader
   122	
   123		err error
   124	}
   125	
   126	func (r *pluginConfirmReader) Read(p []byte) (int, error) {
   127		n, err := r.Reader.Read(p)
   128		if n == 0 {
   129			r.err = err
   130		}
   131		return n, err //nolint:wrapcheck // preserve io.Reader EOF semantics for the scanner
