     1	package cli
     2	
     3	import (
     4		"context"
     5		"fmt"
     6		"io"
     7		"sync"
     8	
     9		"github.com/entireio/cli/cmd/entire/cli/interactive"
    10	)
    11	
    12	type pluginProgressKey struct{}
    13	
    14	// withPluginProgress opts the command into progress reporting. The context
    15	// carries the writer through dependency installs without making library callers
    16	// print to the process's terminal.
    17	func withPluginProgress(ctx context.Context, out io.Writer) context.Context {
    18		return context.WithValue(ctx, pluginProgressKey{}, out)
    19	}
    20	
    21	// startPluginStep reports work before it starts. Stop the spinner before any
    22	// prompt, warning or result is printed. The returned stop is idempotent so a
    23	// deferred cleanup can also cover early returns.
    24	func startPluginStep(ctx context.Context, message string) func() {
    25		out, ok := ctx.Value(pluginProgressKey{}).(io.Writer)
    26		if !ok {
    27			return func() {}
    28		}
    29		if IsAccessibleMode() || !interactive.ShouldStyle(out) {
    30			fmt.Fprintln(out, message)
    31			return func() {}
    32		}
    33		stop := startSpinner(out, message)
    34		var once sync.Once
    35		return func() { once.Do(func() { stop(false) }) }
    36	}
